"""Writes help.json for blitz-lsp: the short help that the hover and the signature help of the editor show.

It is made from the texts of the wiki (tools/wiki/text/<Dialect>/<Category>/<Name>.md), the same files that the command pages of the
wiki are built from:  { "plot": { "summary": "Draws a single pixel ...", "params": { "x": "..." }, "returns": "..." } }
Usage:  python3 tools/generate_lsp_help.py [--output help.json]
"""
import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TEXT = os.path.join(ROOT, "tools", "wiki", "text")


def clean(text):
    # Links and images of the wiki become plain text, the HTML that some pages use is dropped.
    text = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", text)
    text = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", text)
    text = re.sub(r"<[^>]+>", "", text)
    return re.sub(r"[ \t]+", " ", text).strip()


def read(path):
    with open(path, encoding="utf-8") as f:
        body = f.read()
    body = re.sub(r"<!--.*?-->\n?", "", body, flags=re.S)
    lines = body.split("\n")
    summary = []
    params = {}
    returns = ""
    fence = False
    current = None  # The @param or @returns that continues on the next line
    for line in lines:
        if line.lstrip().startswith("```"):
            fence = not fence
            current = None
            continue
        if fence:
            continue
        m = re.match(r"@param\s+(\S+)\s*(.*)$", line)
        if m:
            params[m.group(1).lower()] = m.group(2).strip()
            current = ("param", m.group(1).lower())
            continue
        m = re.match(r"@returns?\s*(.*)$", line)
        if m:
            returns = m.group(1).strip()
            current = ("returns", None)
            continue
        if line.startswith("@"):
            current = None  # @gap, @difference ...
            continue
        if current and line.strip():
            if current[0] == "param":
                params[current[1]] += " " + line.strip()
            else:
                returns += " " + line.strip()
            continue
        current = None
        summary.append(line)
    # The first paragraph is the summary
    paragraph = []
    for line in summary:
        if not line.strip():
            if paragraph:
                break
            continue
        if line.startswith("#") or line.startswith("|") or line.startswith("!["):
            if paragraph:
                break
            continue
        paragraph.append(line.strip())
    entry = {"summary": clean(" ".join(paragraph))}
    if params:
        entry["params"] = {k: clean(v) for k, v in params.items()}
    if returns:
        entry["returns"] = clean(returns)
    return entry


def main():
    out = os.path.join(ROOT, "help.json")
    if "--output" in sys.argv:
        out = sys.argv[sys.argv.index("--output") + 1]
    help = {}
    for dialect in sorted(os.listdir(TEXT)):
        top = os.path.join(TEXT, dialect)
        if not os.path.isdir(top):
            continue
        for folder, _, files in sorted(os.walk(top)):
            for name in sorted(files):
                if not name.endswith(".md") or name.startswith("_"):
                    continue
                entry = read(os.path.join(folder, name))
                key = name[:-3].lower()
                # The same command can be in more than one dialect: the first text with a summary wins.
                if entry["summary"] and (key not in help or not help[key]["summary"]):
                    help[key] = entry
    os.makedirs(os.path.dirname(os.path.abspath(out)), exist_ok=True)
    with open(out, "w", encoding="utf-8", newline="\n") as f:
        json.dump(help, f, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        f.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
